class Solution {
public:
    int longestAlternating(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, 1), right(n, 1);
        for (int i = 1; i < n; ++i) {
            int a = (nums[i] > nums[i - 1]) - (nums[i] < nums[i - 1]);
            int b = i >= 2 ? (nums[i - 1] > nums[i - 2]) - (nums[i - 1] < nums[i - 2]) : 0;
            if (a && (i == 1 || a == -b)) left[i] = left[i - 1] + 1;
            else if (a) left[i] = 2;
        }
        for (int i = n - 2; i >= 0; --i) {
            int a = (nums[i + 1] > nums[i]) - (nums[i + 1] < nums[i]);
            int b = i + 2 < n ? (nums[i + 2] > nums[i + 1]) - (nums[i + 2] < nums[i + 1]) : 0;
            if (a && (i + 2 == n || a == -b)) right[i] = right[i + 1] + 1;
            else if (a) right[i] = 2;
        }
        int ans = *max_element(left.begin(), left.end());
        for (int i = 1; i + 1 < n; ++i) {
            int bridge = (nums[i + 1] > nums[i - 1]) - (nums[i + 1] < nums[i - 1]);
            if (!bridge) continue;
            int L = left[i - 1], R = right[i + 1];
            if (L > 1) {
                int prev = (nums[i - 1] > nums[i - 2]) - (nums[i - 1] < nums[i - 2]);
                if (prev == bridge) L = 1;
            }
            if (R > 1) {
                int next = (nums[i + 2] > nums[i + 1]) - (nums[i + 2] < nums[i + 1]);
                if (next == bridge) R = 1;
            }
            ans = max(ans, L + R);
        }
        return ans;
    }
};
